 "Up to 10 access codes": "Bis zu 10 Zugangscodes",
 "Links, prizes, recommendations and reviews are available to every registered member.": "Links, Preise, Empfehlungen und Bewertungen stehen jedem registrierten Mitglied offen.",
 "Add playback links to any title and they appear on that title’s watch page.": "Fügen Sie Wiedergabe-Links zu einem Titel hinzu; sie erscheinen auf dessen Watch-Seite.",
