 "How to subscribe": "So nimmst du teil",
 "Gift": "Geschenk",
 "Challenge": "Herausforderung",
 "Lottery": "Verlosung",
 "Get the prize by paying points earned from your watch minutes. It usually costs more points, but you get more time — until the prize end date. The downside: it needs more watch points.": "Erhalte den Preis, indem du Punkte bezahlst, die du mit deinen Sehminuten verdient hast. Das kostet meist mehr Punkte, aber du hast mehr Zeit — bis zum Enddatum des Preises. Der Nachteil: Es braucht mehr Sehpunkte.",
 "Subscribe with fewer points, but complete the required actions: watch specific titles, share them, bring friends to register, or collect a number of watch points in a set time. Light on points and fast — but the number of winners is limited to those who finish the conditions first.": "Nimm mit weniger Punkten teil, erfülle aber die geforderten Aktionen: bestimmte Titel ansehen, sie teilen, Freunde zum Registrieren bringen oder eine bestimmte Anzahl Sehpunkte in einer festgelegten Zeit sammeln. Punktesparend und schnell — aber die Zahl der Gewinner ist auf jene begrenzt, die die Bedingungen zuerst erfüllen.",
 "Subscribe with the fewest points — just meet the conditions and win the draw once the required number of participants is reached. The lowest points cost and the most valuable prizes, but the draw is slow: it only happens when enough members join, and winning takes luck.": "Nimm mit den wenigsten Punkten teil — erfülle einfach die Bedingungen und gewinne die Ziehung, sobald die nötige Teilnehmerzahl erreicht ist. Niedrigster Punktebedarf und die wertvollsten Preise, aber die Ziehung dauert: Sie findet erst statt, wenn genug Mitglieder dabei sind, und zum Gewinnen braucht es Glück.",
