 "Subscription modes": "Teilnahmemodi",
 "Every prize needs at least one mode. Gift keeps a start and an end date, challenge runs longer but is limited by quantity, and lottery has no end date and is limited by the number of winners.": "Jeder Preis braucht mindestens einen Modus. Geschenk hat ein Start- und ein Enddatum, Herausforderung läuft länger, ist aber durch die Menge begrenzt, und Verlosung hat kein Enddatum und ist durch die Zahl der Gewinner begrenzt.",
