 "No prizes are ready to claim right now. Earn enough points for a gift or finish a challenge.": "Derzeit kann kein Preis abgeholt werden. Sammeln Sie genug Punkte für ein Geschenk oder schließen Sie eine Herausforderung ab.",
 "No challenge prizes are available right now.": "Derzeit sind keine Herausforderungs-Preise verfügbar.",
 "No lottery prizes are available right now.": "Derzeit sind keine Verlosungspreise verfügbar.",
 "You have not joined or won any prizes yet.": "Sie haben noch an keinem Preis teilgenommen und keinen gewonnen.",
