 "Spend {n} points to claim {title}?": "{n} Punkte ausgeben, um „{title}“ abzuholen?",
 "Your points come from your activity on CineAura, and show what you spent on prizes. Available points = earned minus spent.": "Ihre Punkte stammen aus Ihrer Aktivität auf CineAura und zeigen, was Sie für Preise ausgegeben haben. Verfügbare Punkte = verdiente minus ausgegebene.",
 "Loading your points…": "Ihre Punkte werden geladen …",
