 "You have not spent any points yet.": "Sie haben noch keine Punkte ausgegeben.",
 "Spent before the history was recorded": "Ausgegeben, bevor der Verlauf aufgezeichnet wurde",
 "Prize": "Preis",
 "Claim": "Abholen",
 "Your points could not be loaded. Try again later.": "Ihre Punkte konnten nicht geladen werden. Versuchen Sie es später erneut.",
 "Watch links published": "Veröffentlichte Watch-Links",
 "500 watch links published = 1 point": "500 veröffentlichte Watch-Links = 1 Punkt",
 "Manage prizes": "Preise verwalten",
 "Prize statistics": "Preis-Statistiken",
 "Run sql/prize_admin.sql and then sql/prize_secure.sql in Supabase to enable the prize features.": "Führen Sie sql/prize_admin.sql und danach sql/prize_secure.sql in Supabase aus, um die Preis-Funktionen zu aktivieren.",
 "Prize title": "Preistitel",
 "Prize description": "Preisbeschreibung",
 "Prize image URLs (one per line)": "Bild-URLs des Preises (eine pro Zeile)",
 "Prize video link (YouTube, Vimeo or direct file)": "Videolink des Preises (YouTube, Vimeo oder direkte Datei)",
 "Categories, comma separated (Electronics, Phones, Games)": "Kategorien, durch Kommas getrennt (Elektronik, Telefone, Spiele)",
 "Prize dates": "Preiszeiträume",
