 "New on CineAura": "Neu auf CineAura",
 "The Market, members’ videos and IPTV lists, points and levels: everything we added lately, in one place.": "Der Markt, Videos und IPTV-Listen der Mitglieder, Punkte und Level: alles, was wir zuletzt hinzugefügt haben, an einem Ort.",
 "The Market": "Der Markt",
 "Open your own store and buy or sell products for points. Stores grow through the N, K, M and B tiers.": "Eröffne deinen eigenen Shop und kaufe oder verkaufe Produkte gegen Punkte. Shops steigen durch die Stufen N, K, M und B auf.",
 "Open the Market": "Zum Markt",
 "Recommendations & purchase lists": "Empfehlungen und Einkaufslisten",
