 "New prize code": "Neuer Gewinncode",
 "Members type it on the activation page: it activates (or reactivates) their account with the membership and the months you choose. The same plan still running: the months are added to it.": "Mitglieder geben ihn auf der Aktivierungsseite ein: Er aktiviert (oder reaktiviert) ihr Konto mit der Mitgliedschaft und den Monaten, die du wählst. Läuft derselbe Tarif noch, werden die Monate angehängt.",
 "Members type it in Dashboard > Points > Earn points: the points are added to their balance and count for their level.": "Mitglieder geben ihn unter Dashboard > Punkte > Punkte verdienen ein: Die Punkte kommen auf ihr Guthaben und zählen für ihr Level.",
 "Members type it on a prize before they join it: it takes these points off the points the prize asks for, in every mode that costs points.": "Mitglieder geben ihn bei einem Gewinn ein, bevor sie teilnehmen: Er zieht diese Punkte von den verlangten Punkten ab, in jedem Modus, der Punkte kostet.",
