 "This part of the panel needs the latest SQL: run content.sql, iptv_lists.sql, point_codes.sql, market.sql, packages.sql and then panel_admin.sql in the Supabase SQL editor.": "Dieser Teil des Panels braucht das neueste SQL: Führe content.sql, iptv_lists.sql, point_codes.sql, market.sql, packages.sql und dann panel_admin.sql im SQL-Editor von Supabase aus.",
 "The members you name get this membership by themselves as soon as you save, without typing the serial (an activation for an account never activated, a reactivation for the others). Each one counts as one use.": "Die genannten Mitglieder erhalten diese Mitgliedschaft automatisch beim Speichern, ohne die Seriennummer einzugeben (eine Aktivierung für ein nie aktiviertes Konto, eine Reaktivierung für die anderen). Jedes zählt als eine Verwendung.",
 "The members you name get these points by themselves as soon as you save, without typing the serial. Each one counts as one use.": "Die genannten Mitglieder erhalten diese Punkte automatisch beim Speichern, ohne die Seriennummer einzugeben. Jedes zählt als eine Verwendung.",
 "The members you name find this discount filled in by itself on their next prize entry that costs points, without typing the serial; they can keep it for another prize.": "Die genannten Mitglieder finden diesen Rabatt bei ihrer nächsten Teilnahme an einem Gewinn, der Punkte kostet, automatisch eingetragen, ohne die Seriennummer einzugeben; sie können ihn für einen anderen Gewinn aufheben.",
