 "Membership: account, points and prize packages": "Mitgliedschaft: Konto-, Punkte- und Gewinnpakete",
 "Make the serials of the packages: an activation or reactivation code for an account, a code that adds points, or a code that takes points off a prize. Each one can be used a number of times (each member once) by anybody who types it, by the members who meet your criteria, or by the members you name, who get it by themselves without typing anything.": "Erstelle die Seriennummern der Pakete: einen Aktivierungs- oder Reaktivierungscode für ein Konto, einen Code, der Punkte hinzufügt, oder einen Code, der Punkte vom Preis eines Gewinns abzieht. Jeder kann mehrmals verwendet werden (jedes Mitglied einmal) – von allen, die ihn eingeben, von Mitgliedern, die deine Kriterien erfüllen, oder von Mitgliedern, die du nennst und die ihn automatisch erhalten, ohne etwas einzugeben.",
